mapper.insert:
    	insert into ${newTableName}
		select info.* from CHB_INVESTHOLD_INFO info
    		where info.HOLD_DATE = str_to_date(#{dataBackupDate,jdbcType=VARCHAR},'%Y-%m-%d')

    	insert into ${newTableName}
		select sub.* from  CHB_INVESTHOLD_INFO_SUB sub
    		where sub.HOLD_DATE = str_to_date(#{dataBackupDate,jdbcType=VARCHAR},'%Y-%m-%d')

mapper.update:
    insert into ${newTableName}
    select info.* from CHB_INVESTHOLD_INFO info
		where info.HOLD_DATE >= str_to_date(#{dataBackupDate,jdbcType=VARCHAR},'%Y-%m-%d')

    insert into ${newTableName}
    select sub.* from  CHB_INVESTHOLD_INFO_SUB sub
		where sub.HOLD_DATE >= str_to_date(#{dataBackupDate,jdbcType=VARCHAR},'%Y-%m-%d')
